import { Matrix4 } from 'three';

// scenes.json: the list of AR scenes, generated by `npm run assets:publish` (tools/assets).
//
// Page frame: millimetres on the physical page, origin at the page centre, X to the right,
// Y to the top of the page, Z out of the page (towards the viewer).

/** Where a scene's original Vuforia target lies on the page. */
export interface SceneAnchor {
  /** Target centre in the page frame, mm. */
  center: [number, number];
  /** Target width, mm. The scene's target-local unit is the target width. */
  width: number;
}

export interface SceneAudio {
  /** URL relative to the app base. */
  src: string;
  volume: number;
  loop: boolean;
}

/** Pinch-to-scale settings, from the original PinchScale script. */
export interface ScenePinch {
  /** Name of the scene root node that is scaled. */
  node: string;
  /** Scale limits relative to the node's initial scale. */
  min: number;
  max: number;
  /**
   * Point to scale about when enlarging, in the scene's target-local frame (target width = 1,
   * Y out of the page); when reducing, the point on the page below it, so the scene stays on
   * the page. Absent: the node's own origin, as in the original.
   */
  pivot?: [number, number, number];
}

export interface SceneEntry {
  id: string;
  /** Page id of the tracked page in book-ar-pages, for example "page90". */
  page: string;
  /** GLB URL relative to the app base. */
  model: string;
  /** NFT marker URL prefix relative to the app base (+ .iset, .fset, .fset3). */
  nft: string;
  audio: SceneAudio;
  anchor: SceneAnchor;
  pinch: ScenePinch;
}

export interface ScenesManifest {
  /** Physical page size, mm. */
  page: { width: number; height: number };
  scenes: SceneEntry[];
}

function fail(path: string, expected: string): never {
  throw new Error(`scenes.json: ${path} must be ${expected}`);
}

function objectAt(value: unknown, path: string): Record<string, unknown> {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) fail(path, 'an object');
  return value as Record<string, unknown>;
}

function stringAt(value: unknown, path: string): string {
  if (typeof value !== 'string' || value === '') fail(path, 'a non-empty string');
  return value;
}

function numberAt(value: unknown, path: string, { positive = false } = {}): number {
  if (typeof value !== 'number' || !Number.isFinite(value)) fail(path, 'a finite number');
  if (positive && value <= 0) fail(path, 'positive');
  return value;
}

function booleanAt(value: unknown, path: string): boolean {
  if (typeof value !== 'boolean') fail(path, 'a boolean');
  return value;
}

function parseScene(value: unknown, path: string): SceneEntry {
  const scene = objectAt(value, path);
  const audio = objectAt(scene['audio'], `${path}.audio`);
  const anchor = objectAt(scene['anchor'], `${path}.anchor`);
  const center = anchor['center'];
  if (!Array.isArray(center) || center.length !== 2) fail(`${path}.anchor.center`, '[x, y]');
  const pinch = objectAt(scene['pinch'], `${path}.pinch`);
  const min = numberAt(pinch['min'], `${path}.pinch.min`, { positive: true });
  const max = numberAt(pinch['max'], `${path}.pinch.max`, { positive: true });
  if (max < min) fail(`${path}.pinch.max`, 'at least pinch.min');
  const pivot = pinch['pivot'];
  if (pivot !== undefined && (!Array.isArray(pivot) || pivot.length !== 3)) {
    fail(`${path}.pinch.pivot`, '[x, y, z]');
  }
  return {
    id: stringAt(scene['id'], `${path}.id`),
    page: stringAt(scene['page'], `${path}.page`),
    model: stringAt(scene['model'], `${path}.model`),
    nft: stringAt(scene['nft'], `${path}.nft`),
    audio: {
      src: stringAt(audio['src'], `${path}.audio.src`),
      volume: numberAt(audio['volume'], `${path}.audio.volume`),
      loop: booleanAt(audio['loop'], `${path}.audio.loop`),
    },
    anchor: {
      center: [
        numberAt(center[0], `${path}.anchor.center[0]`),
        numberAt(center[1], `${path}.anchor.center[1]`),
      ],
      width: numberAt(anchor['width'], `${path}.anchor.width`, { positive: true }),
    },
    pinch: {
      node: stringAt(pinch['node'], `${path}.pinch.node`),
      min,
      max,
      ...(pivot
        ? {
            pivot: [0, 1, 2].map((i) => numberAt(pivot[i], `${path}.pinch.pivot[${i}]`)) as [
              number,
              number,
              number,
            ],
          }
        : {}),
    },
  };
}

/** Validates parsed scenes.json content; throws an error naming the first invalid field. */
export function parseScenesManifest(value: unknown): ScenesManifest {
  const manifest = objectAt(value, 'root');
  const page = objectAt(manifest['page'], 'page');
  const scenes = manifest['scenes'];
  if (!Array.isArray(scenes)) fail('scenes', 'an array');
  const parsed = scenes.map((scene, i) => parseScene(scene, `scenes[${i}]`));
  const ids = new Set<string>();
  for (const scene of parsed) {
    if (ids.has(scene.id)) fail(`scene id "${scene.id}"`, 'unique');
    ids.add(scene.id);
  }
  return {
    page: {
      width: numberAt(page['width'], 'page.width', { positive: true }),
      height: numberAt(page['height'], 'page.height', { positive: true }),
    },
    scenes: parsed,
  };
}

export async function loadScenesManifest(url: string): Promise<ScenesManifest> {
  const response = await fetch(url);
  if (!response.ok) throw new Error(`Cannot load ${url}: HTTP ${response.status}`);
  return parseScenesManifest(await response.json());
}

/**
 * Transform from a scene's target-local frame (as exported: target width = 1 unit, Y out of
 * the page, image top towards +Z, image right towards -X) into the page frame in millimetres.
 */
export function anchorMatrix({ center, width }: SceneAnchor): Matrix4 {
  // prettier-ignore
  return new Matrix4().set(
    -width, 0, 0, center[0],
    0, 0, width, center[1],
    0, width, 0, 0,
    0, 0, 0, 1,
  );
}
